#include "test_util.h"

#include <filesystem>

using namespace clxcpp;

static std::string data_dir() { return CLXCPP_TEST_DATA_DIR; }
static std::string ref_dir() { return CLXCPP_TEST_REFERENCE_DIR; }

// The reference files were generated by the Python implementation with the
// relative path "tests/data/<key>.clx", so summaries/JSON embed that path.
static std::string rel_path(const std::string& key) {
  return "tests/data/" + key + ".clx";
}

TEST(parity_summary_samp1) {
  std::string key = "Samp1_20260804_161544_00.06.946";
  auto bytes = read_file_bytes(data_dir() + "/" + key + ".clx");
  clx_file f = parse(bytes, rel_path(key));
  std::string expect = read_file_text(ref_dir() + "/" + key + ".summary.txt");
  CHECK_EQ(f.summary() + "\n", expect);
}

