TEST(export_writes_instrument_naming) {
  std::string key = "Samp1_20260804_161544_00.06.946";
  auto bytes = read_file_bytes(data_dir() + "/" + key + ".clx");
  clx_file f = parse(bytes, rel_path(key));

  std::filesystem::path tmp =
      std::filesystem::temp_directory_path() / "clxcpp_export_test";
  std::filesystem::remove_all(tmp);

  auto written = export_images(f, tmp.string(), {"tiff", "png", "json"});
  CHECK_EQ(written.size(), (std::size_t)5);  // 2x tiff + 2x png + json

  std::vector<std::string> expected = {
      (tmp / "Samp1_20260804_161544_00.06.946_0_16bit.tif").string(),
      (tmp / "Samp1_20260804_161544_00.06.946_0_16bit.png").string(),
      (tmp / "Samp1_20260804_161544_00.06.946_1_16bit.tif").string(),
      (tmp / "Samp1_20260804_161544_00.06.946_1_16bit.png").string(),
      (tmp / "Samp1_20260804_161544_00.06.946_metadata.json").string(),
  };
  CHECK_EQ(written, expected);
  for (auto& p : expected) CHECK(std::filesystem::exists(p));

  std::filesystem::remove_all(tmp);
}

TEST(export_unknown_format_raises) {
  std::string key = "Samp1_20260804_161544_00.06.946";
  auto bytes = read_file_bytes(data_dir() + "/" + key + ".clx");
  clx_file f = parse(bytes, rel_path(key));
  bool threw = false;
  try {
    export_images(f, "out", {"gif"});
  } catch (const std::invalid_argument&) {
    threw = true;
  }
  CHECK(threw);
}
